<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Booking;use App\Support\SeatNotices;use Illuminate\Http\{Request,RedirectResponse};use Illuminate\Support\Facades\Storage;use Illuminate\Validation\Rule;use Illuminate\View\View;use Symfony\Component\HttpFoundation\StreamedResponse;
class BookingController extends Controller{
 public function __construct(){$this->middleware('permission:list-bookings')->only(['index','show','paymentProof']);$this->middleware('permission:edit-bookings')->only(['update','updateSeats','sendSeatNotice']);$this->middleware('permission:delete-bookings')->only('destroy');}
 public function index(Request $r):View{$bookings=Booking::with(['tour.translations','departure'])->when($r->filled('q'),fn($q)=>$q->where(fn($x)=>$x->where('reference','like','%'.$r->q.'%')->orWhere('first_name','like','%'.$r->q.'%')->orWhere('last_name','like','%'.$r->q.'%')->orWhere('email','like','%'.$r->q.'%')->orWhere('phone','like','%'.$r->q.'%')))->when($r->filled('type'),fn($q)=>$q->where('type',$r->type))->when($r->filled('status'),fn($q)=>$q->where('status',$r->status))->when($r->filled('payment_status'),fn($q)=>$q->where('payment_status',$r->payment_status))->latest()->paginate(20)->withQueryString();return view('admin.bookings.index',compact('bookings'));}
 public function show(Booking $booking):View{$booking->load(['tour.translations','departure','pickupPoint.translations','passengers.pickupPoint.translations']);return view('admin.bookings.show',['booking'=>$booking,'seatBlocker'=>SeatNotices::blocker($booking)]);}
 public function update(Request $r,Booking $booking):RedirectResponse{$d=$r->validate(['status'=>['required',Rule::in(['new','contacted','confirmed','cancelled','completed'])],'payment_status'=>['required',Rule::in(array_keys(Booking::PAYMENT_STATUSES))],'amount_paid'=>['nullable','numeric','min:0']]);$d['amount_paid']=$d['amount_paid']??0;$booking->update($d);return back()->with('message','Booking updated.');}
 public function updateSeats(Request $r,Booking $booking):RedirectResponse{$d=$r->validate(['seats'=>['array'],'seats.*'=>['nullable','string','max:10']]);foreach($booking->passengers as $passenger){if(array_key_exists($passenger->id,$d['seats']??[]))$passenger->update(['seat_number'=>$d['seats'][$passenger->id]?:null]);}return back()->with('message','Seat numbers saved.');}
 public function sendSeatNotice(Booking $booking):RedirectResponse{if($reason=SeatNotices::blocker($booking))return back()->withErrors(['seats'=>$reason]);SeatNotices::send($booking);return back()->with('message','Seat numbers emailed to '.$booking->email.'.');}
 public function paymentProof(Booking $booking):StreamedResponse{abort_unless($booking->payment_proof&&Storage::disk('local')->exists($booking->payment_proof),404);return Storage::disk('local')->response($booking->payment_proof);}
 public function destroy(Booking $booking):RedirectResponse{$booking->delete();return redirect()->route('bookings.index')->with('message','Booking deleted.');}
}
